mapper.select:
SELECT
    sou_project.*
FROM scc_sou_project sou_project
LEFT JOIN scc_sou_inq_project inq_project on inq_project.PROJECT_ID = sou_project.PROJECT_ID
WHERE
    sou_project.SOU_TYPE = 'inq'

    AND sou_project.SOU_NO LIKE concat('%', concat(#{souNo}, '%'))


    AND sou_project.SOU_NAME LIKE concat('%', concat(#{souName}, '%'))


    AND inq_project.EXT_PROJECT_STATUS = #{extProjectStatus}


    AND sou_project.SCORE_RULE_TYPE = #{scoreRuleType}


    AND sou_project.CREATED_ID = #{createdId}


    AND (
        sou_project.CREATED_BY LIKE concat('%', concat(#{createdBy}, '%'))
        OR
        sou_project.CREATED_FULL_NAME LIKE concat('%', concat(#{createdBy}, '%'))
    )


    AND sou_project.CREATE_APPROVAL_STATUS = #{createApprovalStatus}


    AND sou_project.CREATION_DATE >= #{creationDateFrom}


    AND sou_project.CREATION_DATE <= #{creationDateTo}


    AND sou_project.PUBLISH_TIME >= #{publishTimeFrom}


    AND sou_project.PUBLISH_TIME <= #{publishTimeTo}


    AND exists (
        SELECT item.PROJECT_ID from scc_sou_item item
        WHERE item.PROJECT_ID = sou_project.PROJECT_ID
        AND item.ITEM_CODE LIKE concat('%', concat(#{itemCode}, '%'))
    )


    AND exists (
        SELECT item.PROJECT_ID from scc_sou_item item
        WHERE item.PROJECT_ID = sou_project.PROJECT_ID
        AND item.ITEM_DESC LIKE concat('%', concat(#{itemDesc}, '%'))
    )


    AND exists (
        SELECT inq_item.PROJECT_ID from scc_sou_inq_item inq_item
        WHERE inq_item.PROJECT_ID = sou_project.PROJECT_ID
        AND inq_item.EXT_MATERIAL_MODEL LIKE concat('%', concat(#{extMaterialModel}, '%'))
    )


    AND (
        inq_project.CREATE_USER_ORG_OU_CODE LIKE concat('%', concat(#{createUserOrgOuName}, '%'))
        OR
        inq_project.CREATE_USER_ORG_OU_NAME LIKE concat('%', concat(#{createUserOrgOuName}, '%'))
    )

ORDER BY sou_project.SOU_NO desc

SELECT sou_project.PROJECT_ID, sou_project.PROCESS_CONFIG_ID, sou_project.SOU_NO, sou_project.SOU_NAME, sou_project.CURRENT_ROUND, sou_project.PUBLISH_SCOPE, sou_project.PROJECT_STATUS, sou_order.ORDER_NO, sou_order.ORDER_STATUS, sou_project.SIGN_UP_END_TIME, sou_project.ORDER_START_TIME, sou_project.ORDER_END_TIME, sou_project.PUBLISH_TIME, sou_project.ALLOW_WITHDRAW, sou_project.CREATED_BY, sou_order.CREATED_FULL_NAME, sou_order.LAST_UPDATED_FULL_NAME, vendor.JOIN_ROUND, case when vendor.SIGN_UP_STATUS is null then 'NO_SIGN_UP' else vendor.SIGN_UP_STATUS end sign_up_status FROM scc_sou_project sou_project LEFT JOIN scc_sou_inq_project inq_project on sou_project.PROJECT_ID = inq_project.PROJECT_ID LEFT JOIN scc_sou_order sou_order ON sou_project.PROJECT_ID = sou_order.PROJECT_ID AND sou_order.ROUND = sou_project.CURRENT_ROUND AND sou_order.VENDOR_ID = #{queryParam.vendorId} LEFT JOIN scc_sou_vendor vendor on vendor.PROJECT_ID = sou_project.PROJECT_ID and vendor.VENDOR_ID = #{queryParam.vendorId} WHERE sou_project.PROJECT_STATUS NOT IN ('DRAFT') and sou_project.SOU_TYPE = #{souType}
AND sou_project.SOU_NO LIKE concat('%', concat(#{queryParam.souNo}, '%'))
AND sou_project.SOU_NAME LIKE concat('%', concat(#{queryParam.souName}, '%'))
AND inq_project.EXT_PROJECT_STATUS = #{queryParam.extProjectStatus}
AND ( sou_project.PUBLISH_SCOPE = 'OPEN_TENDER' AND EXISTS( SELECT * FROM scc_sou_item sou_item where sou_item.PROJECT_ID = sou_project.PROJECT_ID
AND sou_item.ITEM_DESC LIKE concat('%', concat(#{queryParam.itemDesc}, '%'))
) OR sou_project.PUBLISH_SCOPE = 'INVITE_TENDER' AND EXISTS( SELECT PROJECT_ID FROM scc_sou_vendor WHERE PROJECT_ID = sou_project.PROJECT_ID AND VENDOR_ID = #{queryParam.vendorId}
AND EXISTS ( SELECT sou_item.SOU_ITEM_ID FROM scc_sou_item sou_item WHERE sou_item.PROJECT_ID = sou_project.PROJECT_ID AND sou_item.ITEM_ID = #{queryParam.itemId} )
and exists ( SELECT temp1.SOU_ITEM_ID FROM scc_sou_item temp1 join scc_sou_inq_item temp2 on temp1.SOU_ITEM_ID=temp2.SOU_ITEM_ID WHERE temp1.PROJECT_ID = sou_project.PROJECT_ID and temp1.ITEM_DESC LIKE concat('%', concat(#{queryParam.itemDesc}, '%')) and temp1.ITEM_CODE LIKE concat('%', concat(#{queryParam.extensions.itemCode}, '%'))
and temp2.EXT_BRAND LIKE concat('%', concat(#{queryParam.extensions.extBrand}, '%'))
and temp2.EXT_MATERIAL_MODEL LIKE concat('%', concat(#{queryParam.extensions.extMaterialModel}, '%'))
)
) )
AND ( sou_order.PROJECT_ID IS NULL OR sou_order.ORDER_STATUS = 'DRAFT' )
AND sou_order.ORDER_STATUS = #{queryParam.orderStatus}
AND inq_project.CREATE_USER_ORG_OU_NAME LIKE concat('%', concat(#{queryParam.createUserOrgOuName}, '%'))
AND sou_project.CREATED_FULL_NAME LIKE concat('%', concat(#{queryParam.buyerNickName}, '%'))
order by sou_project.ORDER_END_TIME DESC, sou_project.SOU_NO desc

SELECT * FROM ( SELECT sou_project.SOU_NO, sou_project.PROJECT_STATUS, sou_project.CURRENT_ROUND, sou_item.*, inq_item.EXT_MATERIAL_MODEL, sou_project.CREATED_BY BUYER_USERNAME, sou_project.CREATED_FULL_NAME BUYER_NICK_NAME, sou_project.creation_date SOU_CREATION_DATE, sou_project.ORDER_END_TIME, sou_project.EXT_APPLICANT, sou_project.EXT_ORG_OU_ID FROM scc_sou_item sou_item LEFT JOIN scc_sou_inq_item inq_item ON sou_item.SOU_ITEM_ID = inq_item.SOU_ITEM_ID LEFT JOIN scc_sou_project sou_project ON sou_item.PROJECT_ID = sou_project.PROJECT_ID WHERE sou_project.SOU_TYPE = 'inq'
AND sou_project.SOU_NO LIKE concat('%', concat(#{souNo}, '%'))
AND sou_project.PROJECT_STATUS = #{projectStatus}
AND sou_project.CREATED_BY = #{buyerUsername}
AND sou_item.ITEM_CODE LIKE concat('%', concat(#{itemCode}, '%'))
AND sou_item.ITEM_DESC LIKE concat('%', concat(#{itemDesc}, '%'))
AND inq_item.EXT_MATERIAL_MODEL LIKE concat('%', concat(#{extMaterialModel}, '%'))
AND sou_project.CREATION_DATE >= #{souCreationDateFrom}
AND sou_project.CREATION_DATE <= #{souCreationDateTo}
AND sou_project.ORDER_END_TIME >= #{orderEndTimeFrom}
AND sou_project.ORDER_END_TIME <= #{orderEndTimeTo}
) tt WHERE 1 = 1
AND tt.ORDER_COUNT = #{orderCount}
ORDER BY tt.SOU_NO desc, tt.SOU_ITEM_ID asc
